import machine
import neopixel
import time


# --- Configuration ---
# Updated to your specific setup
PIN_NUM = 16        # Connected to GPIO 16
NUM_PIXELS = 3      # There are 3 NeoPixels in a row

# --- Initialization ---
pin = machine.Pin(PIN_NUM, machine.Pin.OUT)
np = neopixel.NeoPixel(pin, NUM_PIXELS)

# --- Color Definitions (R, G, B) ---
GREEN = (0, 255, 0)
OFF = (0, 0, 0)

print("Blinking the first NeoPixel on GPIO 16... Press Ctrl+C to stop.")

try:
    while True:
        # 1. Turn ONLY the first LED ON
        # In Python/MicroPython, indexing starts at 0.
        np[0] = GREEN       
        np.write()         
        time.sleep(0.5)    
        
        # 2. Turn ONLY the first LED OFF
        np[0] = OFF        
        np.write()         
        time.sleep(0.5)    

except KeyboardInterrupt:
    # Turn off the LED when you stop the script
    np[0] = OFF
    np.write()
    print("\nProgram stopped.")
    
    
